/**
 * @file sim_board.h
 * @brief Board model behind the simulator (SPEC section 18): the host's
 *        output pins, the DRV8411 inputs generated by the shared PWM policy,
 *        the motor-enable AND gate, an IS31FL3218-compatible register file, the
 *        J5 servo request and signal, an HC-SR04 on J1 and the production MCU
 *        policy stepped every simulated millisecond.
 *
 * The model is single-threaded and clock-agnostic: callers serialise access
 * and decide how time moves (keel__board_advance()). The simulator backend
 * wraps it with locks and a real-time or virtual clock; the reference tests
 * drive it directly. Each keel__board_* function implements the matching
 * port.h hook, including the backend fault latch, the stop epoch and the
 * interlocks.
 *
 * SPEC refers to the libkeel specification, software/libkeel/docs/spec.md.
 */
#ifndef KEEL_SIM_BOARD_H
#define KEEL_SIM_BOARD_H

#include <stddef.h>
#include <stdint.h>

#include "backend/pwm_policy.h"
#include "backend/sim/mcu/mcu_policy.h"
#include "keel/port.h"

/** @brief Model constants. */
enum keel__board_constant {
    KEEL__BOARD_STEP_US = 1000,     /**< The MCU policy runs every millisecond. */
    KEEL__BOARD_LED_REGISTERS = 0x18, /**< LED driver registers 0x00..0x17. */
    KEEL__BOARD_LED_ADDRESS = 0x54, /**< LED driver I2C address. */
    /** A servo request needs the motors quiet for longer than one MCU
     *  sampling period (port.h interlocks). */
    KEEL__BOARD_SERVO_IDLE_US = 3000,
    KEEL__BOARD_ECHO_DELAY_US = 500,    /**< HC-SR04: trigger to echo rise. */
    KEEL__BOARD_ECHO_NOTHING_US = 38000, /**< HC-SR04: echo width with nothing in range. */
    KEEL__BOARD_EDGES = 8               /**< ECHO edges buffered until drained. */
};

/** @brief HC-SR04 echo phases (keel__sim_board::echo_phase). */
enum keel__echo_phase {
    KEEL__ECHO_IDLE = 0,      /**< No echo in progress. */
    KEEL__ECHO_SCHEDULED = 1, /**< Triggered; the rise is due at echo_rise_us. */
    KEEL__ECHO_HIGH = 2       /**< ECHO HIGH until echo_fall_us. */
};

/** @brief The simulated board. All fields belong to the caller's lock. */
typedef struct keel__sim_board {
    uint64_t now_us;              /**< Model time. */
    uint64_t next_step_us;        /**< Time of the next MCU step. */
    uint64_t origin_us;           /**< Model time of MCU time zero. */
    uint32_t outputs;             /**< Host output levels (KEEL_OUT_*). */
    keel_port_motor_command motor; /**< Stored motor command. */
    uint64_t motion_start_us;     /**< Phase anchor of the PWM pattern. */
    uint32_t levels;              /**< Motor line levels (::keel__pwm_line). */
    int pwm_edge;                 /**< A motor line changed since the last step. */
    uint8_t enable_edges;         /**< ENABLE edges since the last step. */
    uint8_t heartbeat_falls;      /**< Heartbeat falls since the last step. */
    uint32_t falls_total;         /**< Heartbeat falls since the model started. */
    int fault_edge;               /**< Hardware-fault pulse for the next step. */
    int fault_low;                /**< Hardware-fault line held LOW (test hook). */
    safety_state mcu;             /**< Production MCU policy state. */
    safety_output permit;         /**< Its outputs after the last step. */
    uint32_t buttons;             /**< Buttons held (::keel_button bits). */
    int32_t range_mm;             /**< Nearest object in mm; -1 for none. */
    int sensor_lockout;           /**< MCU sensor strike lockout. */
    int armed_stuck;              /**< ARMED reads HIGH whatever the gate does. */
    uint64_t coast_since_us;      /**< Time the motor command last became COAST. */
    int servo_request;            /**< SERVO_REQUEST level (BCM19). */
    uint32_t servo_pulse_us;      /**< Pulse generated for J5; 0 = signal off. */
    uint64_t servo_until_us;      /**< Lease end: the model ends the burst here by itself. */
    uint32_t echo_phase;          /**< ::keel__echo_phase. */
    uint64_t echo_rise_us;        /**< Scheduled echo rise. */
    uint64_t echo_fall_us;        /**< Scheduled echo fall. */
    keel_port_edge edges[KEEL__BOARD_EDGES]; /**< ECHO edges not yet drained. */
    uint32_t edge_count;          /**< Entries in edges. */
    uint32_t fail_gpio_writes;    /**< Control output writes still to fail. */
    uint32_t fail_gpio_reads;     /**< Input reads still to fail. */
    uint32_t fail_i2c;            /**< I2C transactions still to fail. */
    uint32_t fail_pwm_writes;     /**< Generator line writes still to fail. */
    uint64_t pending_lateness_us; /**< Lateness of the next generator wake. */
    int pwm_stall;                /**< The generator makes no passes. */
    uint64_t scheduled_wake_us;   /**< The generator's latest scheduled pass. */
    keel__pwm_budget budget;      /**< Lateness budget. */
    uint8_t led_registers[KEEL__BOARD_LED_REGISTERS]; /**< LED driver registers. */
    uint8_t led_output[3 * KEEL_LED_COUNT];          /**< Latched PWM values. */
    keel_port_fault fault;        /**< Backend fault latch (status OK when clear). */
    uint32_t newest_epoch;        /**< Newest stop epoch seen. */
    keel_port_stats stats;        /**< Generator statistics. */
} keel__sim_board;

/** @brief Starts the model at @p now_us with the MCU freshly reset. */
void keel__board_init(keel__sim_board *board, uint64_t now_us);
/** @brief Moves model time to @p target_us, stepping the generator and the MCU every 1 ms. */
void keel__board_advance(keel__sim_board *board, uint64_t target_us);
/** @brief Level of ARMED: MCU permit AND ENABLE AND the fault line (or stuck HIGH). */
int keel__board_armed(const keel__sim_board *board);
/** @brief Latches a backend fault (first wins) and self-stops: ENABLE LOW and
 *  coast, never the heartbeat. @return @p status. */
int32_t keel__board_latch(keel__sim_board *board, int32_t status, uint32_t cause,
                          int32_t os_error, uint64_t detail);
/** @brief read_inputs hook. */
int32_t keel__board_read(keel__sim_board *board, uint32_t *inputs);
/** @brief write_outputs hook. */
int32_t keel__board_write_outputs(keel__sim_board *board, uint32_t mask, uint32_t values,
                                  uint32_t stop_epoch);
/** @brief write_motors hook (order of SPEC 17.5). */
int32_t keel__board_write_motors(keel__sim_board *board, const keel_port_motor_command *command);
/** @brief emergency_disable hook. */
int32_t keel__board_emergency_disable(keel__sim_board *board, uint32_t stop_epoch);
/** @brief get_fault hook. */
int32_t keel__board_get_fault(const keel__sim_board *board, keel_port_fault *out);
/** @brief reset_fault hook. */
int32_t keel__board_reset_fault(keel__sim_board *board);
/** @brief servo hook (SERVO_REQUEST and the J5 signal). */
int32_t keel__board_servo(keel__sim_board *board, const keel_port_servo_command *command);
/** @brief range_trigger hook (HC-SR04). */
int32_t keel__board_range_trigger(keel__sim_board *board, uint32_t *out_echo_high);
/** @brief range_edges hook: drains buffered ECHO edges. */
int32_t keel__board_range_edges(keel__sim_board *board, keel_port_edge *edges, uint32_t capacity,
                                uint32_t *out_count);
/** @brief i2c_write hook (LED driver register file). */
int32_t keel__board_i2c(keel__sim_board *board, uint8_t address, uint8_t reg,
                        const uint8_t *data, size_t count);
/** @brief get_stats hook. */
int32_t keel__board_stats(const keel__sim_board *board, keel_port_stats *out);
/** @brief sim_set hook: applies a ::keel_sim_item stimulus. */
int32_t keel__board_set(keel__sim_board *board, uint32_t item, int32_t value);
/** @brief sim_get_state hook: fills the ground truth. */
int32_t keel__board_state(const keel__sim_board *board, keel_sim_state *out);

#endif /* KEEL_SIM_BOARD_H */
